def transform(grid):
    grid = np.asarray(grid)
    bg = background(grid)
    out = np.full((4, 4), bg, dtype=int)
    emit(out, "Allocate a 4x4 background canvas: four 2x2 quadrants, one per L-shaped piece.")
    for o in objects(grid, bg=bg):
        g = o["grid"]
        if g.shape != (2, 2):
            continue
        miss = [(r, c) for r in range(2) for c in range(2) if g[r, c] == bg]
        if len(miss) != 1:
            continue
        r, c = miss[0]
        y0, x0 = 2 * (1 - r), 2 * (1 - c)
        for dy in range(2):
            for dx in range(2):
                if g[dy, dx] != bg:
                    out[y0 + dy, x0 + dx] = g[dy, dx]
        names = {(0, 0): "top-left", (0, 1): "top-right", (1, 0): "bottom-left", (1, 1): "bottom-right"}
        emit(out, f"Colour {o['colour']} piece is missing its {names[(r, c)]} corner, "
                  f"so it goes into the opposite ({names[(1 - r, 1 - c)]}) quadrant with the gap facing the centre.")
    emit(out, "All four pieces placed; the missing corners form the empty 2x2 centre.")
    return out
